import { Redis } from '@upstash/redis';

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore — generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';

interface Env {
  WORKER_SELF_REFERENCE: {
    fetch(input: string, init?: RequestInit): Promise<Response>;
  };
  CRON_SECRET?: string;
  UPSTASH_REDIS_URL?: string;
  UPSTASH_REDIS_TOKEN?: string;
}

interface WorkerContext {
  waitUntil(promise: Promise<unknown>): void;
}

interface ScheduledEvent {
  cron: string;
  scheduledTime: number;
}

interface RateLimitConfig {
  windowMs: number;
  maxRequests: number;
}

const TIERS = {
  youtube: { windowMs: 60_000, maxRequests: 60 },
  ai: { windowMs: 60_000, maxRequests: 20 },
  compute: { windowMs: 60_000, maxRequests: 120 },
  resolve: { windowMs: 60_000, maxRequests: 60 },
  external: { windowMs: 60_000, maxRequests: 80 },
} as const satisfies Record<string, RateLimitConfig>;

type Tier = keyof typeof TIERS;

const SECURITY_HEADERS = {
  'X-Frame-Options': 'DENY',
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
  'Strict-Transport-Security': 'max-age=63072000; includeSubDomains; preload',
} as const;

/** Per-isolate fallback when Upstash is unavailable. */
const memoryWindows = new Map<string, number[]>();
let redis: Redis | null = null;

function getRedis(env: Env): Redis | null {
  if (redis) return redis;
  if (!env.UPSTASH_REDIS_URL || !env.UPSTASH_REDIS_TOKEN) return null;
  redis = new Redis({
    url: env.UPSTASH_REDIS_URL,
    token: env.UPSTASH_REDIS_TOKEN,
  });
  return redis;
}

function checkMemoryRateLimit(
  key: string,
  config: RateLimitConfig,
  now: number,
): { allowed: boolean; remaining: number; reset: number } {
  const windowStart = now - config.windowMs;
  const timestamps = (memoryWindows.get(key) ?? []).filter((t) => t > windowStart);

  if (timestamps.length >= config.maxRequests) {
    const oldest = timestamps[0] ?? now;
    const reset = Math.max(1, Math.ceil((oldest + config.windowMs - now) / 1000));
    memoryWindows.set(key, timestamps);
    return { allowed: false, remaining: 0, reset };
  }

  timestamps.push(now);
  memoryWindows.set(key, timestamps);
  return {
    allowed: true,
    remaining: config.maxRequests - timestamps.length,
    reset: 0,
  };
}

async function checkRateLimit(
  env: Env,
  tier: Tier,
  identifier: string,
): Promise<{ allowed: boolean; remaining: number; reset: number }> {
  const config = TIERS[tier];
  const key = `rl:${tier}:${identifier}`;
  const now = Date.now();
  const windowStart = now - config.windowMs;

  const client = getRedis(env);
  if (!client) return checkMemoryRateLimit(key, config, now);

  try {
    await client.zremrangebyscore(key, 0, windowStart);
    const count = await client.zcard(key);

    if (count >= config.maxRequests) {
      const oldest = await client.zrange(key, 0, 0, { withScores: true });
      // Upstash returns flat [member, score] for withScores.
      const oldestScore =
        typeof oldest?.[1] === 'number'
          ? oldest[1]
          : typeof oldest?.[0] === 'object' &&
              oldest[0] !== null &&
              'score' in oldest[0]
            ? Number((oldest[0] as { score: number }).score)
            : now;
      const reset = Math.max(
        1,
        Math.ceil((oldestScore + config.windowMs - now) / 1000),
      );
      return { allowed: false, remaining: 0, reset };
    }

    await client.zadd(key, { score: now, member: `${now}-${Math.random()}` });
    await client.expire(key, Math.ceil(config.windowMs / 1000) + 1);

    return {
      allowed: true,
      remaining: config.maxRequests - count - 1,
      reset: 0,
    };
  } catch {
    return checkMemoryRateLimit(key, config, now);
  }
}

function clientIp(request: Request): string {
  const forwarded = request.headers.get('x-forwarded-for');
  return (
    request.headers.get('cf-connecting-ip') ??
    forwarded?.split(',')[0]?.trim() ??
    'unknown'
  );
}

function tierFor(pathname: string): Tier | null {
  if (!pathname.startsWith('/api/')) return null;
  // Internal routes are called by cron/health monitors, not end users.
  if (pathname.startsWith('/api/internal/')) return null;
  if (pathname.startsWith('/api/ai/')) return 'ai';
  if (pathname.startsWith('/api/youtube/resolve')) return 'resolve';
  if (pathname.includes('seo-score')) return 'compute';
  return 'youtube';
}

function applyHeaders(response: Response, requestId: string): Response {
  const headers = new Headers(response.headers);
  for (const [key, value] of Object.entries(SECURITY_HEADERS)) {
    headers.set(key, value);
  }
  headers.set('x-request-id', requestId);
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

function rateLimitResponse(
  result: { reset: number },
  tier: Tier,
): Response {
  return new Response(
    JSON.stringify({
      success: false,
      error: {
        code: 'RATE_LIMITED',
        message: `Too many requests. Please wait ${result.reset} seconds.`,
      },
    }),
    {
      status: 429,
      headers: {
        'content-type': 'application/json',
        'Retry-After': String(result.reset),
        'X-RateLimit-Limit': String(TIERS[tier].maxRequests),
        'X-RateLimit-Remaining': '0',
        'X-RateLimit-Reset': String(
          Math.floor(Date.now() / 1000) + result.reset,
        ),
        ...SECURITY_HEADERS,
      },
    },
  );
}

const worker = {
  async fetch(
    request: Request,
    env: Env,
    ctx: WorkerContext,
  ): Promise<Response> {
    const requestId = crypto.randomUUID();
    const { pathname } = new URL(request.url);
    const tier = tierFor(pathname);

    if (tier) {
      const result = await checkRateLimit(env, tier, clientIp(request));

      if (!result.allowed) {
        return applyHeaders(rateLimitResponse(result, tier), requestId);
      }

      const response = await handler.fetch(request, env, ctx);
      const headers = new Headers(response.headers);
      headers.set('X-RateLimit-Remaining', String(result.remaining));

      return applyHeaders(
        new Response(response.body, {
          status: response.status,
          statusText: response.statusText,
          headers,
        }),
        requestId,
      );
    }

    return applyHeaders(await handler.fetch(request, env, ctx), requestId);
  },

  async scheduled(
    _event: ScheduledEvent,
    env: Env,
    ctx: WorkerContext,
  ): Promise<void> {
    if (!env.CRON_SECRET) {
      console.error('[cron] CRON_SECRET is not configured');
      return;
    }

    ctx.waitUntil(
      (async () => {
        const response = await env.WORKER_SELF_REFERENCE.fetch(
          'https://yttools.pro/api/internal/rankings-snapshot',
          {
            headers: {
              authorization: `Bearer ${env.CRON_SECRET}`,
            },
          },
        );

        if (!response.ok) {
          console.error('[cron] rankings snapshot failed', {
            status: response.status,
          });
        }
      })(),
    );
  },
};

export default worker;

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
